

CREATE TABLE `cart_cart` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `data` text,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8;

ALTER TABLE `xcart_orders`
  CHANGE COLUMN `shipping_total_net` `shipping_total_net` DECIMAL(12,2) NULL DEFAULT NULL AFTER `cart_number`,
  CHANGE COLUMN `shipping_total_gst` `shipping_total_gst` DECIMAL(12,2) NULL DEFAULT NULL AFTER `shipping_total_net`,
  CHANGE COLUMN `shipping_total_pst` `shipping_total_pst` DECIMAL(12,2) NULL DEFAULT NULL AFTER `shipping_total_gst`,
  CHANGE COLUMN `shipping_total_gross` `shipping_total_gross` DECIMAL(12,2) NULL DEFAULT NULL AFTER `shipping_total_pst`,
  CHANGE COLUMN `product_total_net` `product_total_net` DECIMAL(12,2) NULL DEFAULT NULL AFTER `shipping_total_gross`,
  CHANGE COLUMN `product_total_gst` `product_total_gst` DECIMAL(12,2) NULL DEFAULT NULL AFTER `product_total_net`,
  CHANGE COLUMN `product_total_pst` `product_total_pst` DECIMAL(12,2) NULL DEFAULT NULL AFTER `product_total_gst`,
  CHANGE COLUMN `product_total_gross` `product_total_gross` DECIMAL(12,2) NULL DEFAULT NULL AFTER `product_total_pst`,
  CHANGE COLUMN `total_net` `total_net` DECIMAL(12,2) NULL DEFAULT NULL AFTER `product_total_gross`,
  CHANGE COLUMN `total_gst` `total_gst` DECIMAL(12,2) NULL DEFAULT NULL AFTER `total_net`,
  CHANGE COLUMN `total_pst` `total_pst` DECIMAL(12,2) NULL DEFAULT NULL AFTER `total_gst`,
  CHANGE COLUMN `total_gross` `total_gross` DECIMAL(12,2) NULL DEFAULT NULL AFTER `total_pst`,
  CHANGE COLUMN `tax_info_taxed_subtotal` `tax_info_taxed_subtotal` DECIMAL(12,2) NULL DEFAULT NULL AFTER `tax_info_display_cart_products_tax_rates`,
  CHANGE COLUMN `tax_info_taxed_discounted_subtotal` `tax_info_taxed_discounted_subtotal` DECIMAL(12,2) NULL DEFAULT NULL AFTER `tax_info_taxed_subtotal`,
  CHANGE COLUMN `tax_info_taxed_shipping` `tax_info_taxed_shipping` DECIMAL(12,2) NULL DEFAULT NULL AFTER `tax_info_taxed_discounted_subtotal`,
  CHANGE COLUMN `referer_id` `referer_id` INT(11) NULL DEFAULT NULL AFTER `vn_status`;

ALTER TABLE `pages_page`
  ADD COLUMN `no_index` TINYINT(1) NOT NULL DEFAULT '0' AFTER `content_short`;

ALTER TABLE `xcart_product_videos`
  DROP INDEX `pid`,
  ADD INDEX `pid` (`product_id`, `id`, `video`);

CREATE TABLE `pages_pages_storefront_link` (
  `storefront_id` INT(11) NOT NULL,
  `page_id` INT(11) NOT NULL,
  PRIMARY KEY (`storefront_id`, `page_id`)
)
  COLLATE='utf8_general_ci'
  ENGINE=InnoDB;

ALTER TABLE `order_extra`
  ADD COLUMN `purchase_order` TEXT NULL DEFAULT NULL COMMENT 'Purchase order info' AFTER `payment_operator_id`;

ALTER TABLE `xcart_orders`
  ADD COLUMN `user_id` INT(11) UNSIGNED NULL DEFAULT NULL AFTER `orderid`;

ALTER TABLE `xcart_order_groups`
  CHANGE COLUMN `shippingid` `shippingid` INT(11) NULL DEFAULT NULL AFTER `manufacturerid`;

ALTER TABLE `xcart_orders`
  CHANGE COLUMN `cart_number` `cart_number` INT(11) UNSIGNED NULL DEFAULT NULL AFTER `unfreeze_cb_status`;

DELETE FROM `pages_page`;
INSERT INTO `pages_page` (`id`, `parent_id`, `root`, `lft`, `rgt`, `level`, `is_published`, `is_index`, `name`, `url`, `file`, `view`, `view_children`, `sorting`, `created_at`, `updated_at`, `published_at`, `content`, `content_short`, `no_index`) VALUES
  (1, NULL, 1, 1, 2, 1, 1, 0, 'Terms of Use', 'terms-of-use', NULL, 'page_2column.tpl', NULL, NULL, '2017-07-19 07:25:11', '2018-04-27 03:57:36', '2017-07-19 07:57:00', '<div class="large-2column">\r\n<h2>1. Introduction</h2>\r\n<p><strong>1.1</strong> "S3 Stores" is the collective name for these pages, and is owned by the makers of these pages. All use of S3 Stores\' information, services or products implies acceptance of the Terms and Conditions of Use outlined below.</p>\r\n<p><strong>1.2</strong> S3 Stores reserves the right to modify these Terms and Conditions of Use at any time. The modifications take effect from the moment of posting them on the site, or the moment of notification by email, whichever occurs first.</p>\r\n<p><strong>1.3</strong> You agree to check these Terms and Conditions of Use periodically so you may always remain aware of any modifications. As long as you continue to use this site, you express acceptance of the Terms of Use and also accept that our notification of changes to these Terms of Use is also reasonable. You acknowledge and agree that S3 Stores may deny you access to or use of all or part of this website without prior notice if you engage in any conduct or activities that S3 Stores in its sole discretion believes violates any of these Terms and Conditions of Use, or violates the rights of S3 Stores, or is otherwise inappropriate for continued access to and use of this website.</p>\r\n<h2>2. Restrictions On Use</h2>\r\n<p><strong>2.1</strong> S3 Stores offers this website and its content and services as is, with no warranties as to performance, results, or operation without interruption. S3 Stores does not accept any responsibility for failure of services from outside being used on this site, nor does it accept responsibility for any downtime of our or any other of our suppliers\' servers. S3 Stores reserves the right to alter or delete the products, services and information available on this website at any time.</p>\r\n<p><strong>2.2</strong> Links to third-party sites are provided to you only as a convenience, and do not imply endorsement by S3 Stores or any affiliation with or endorsement by the owner of the linked site. S3 Stores is not responsible for the content of any linked site or any consequences of making the link.</p>\r\n<p><strong>2.3</strong> In exchange for use of this website, you agree that any information you submit to us will be current and complete and will not violate the rights of any third parties, and you agree to defend, indemnify, and hold harmless S3 Stores and content suppliers, and their successors against any claims by third parties alleging facts in breach of these representations.</p>\r\n<p><strong>2.4</strong> All content included on this website, including text, graphics, logos, buttons, icons, and images, is the property of S3 Stores, content suppliers, or other licensors, with ownership as indicated by specific copyright and trademark notices and/or context, and is protected by Canadian and international copyright and trademark laws. You may not copy, print, or distribute pages, text, images, e-books, or other content on this website without the express written consent of S3 Stores or the applicable copyright owners.</p>\r\n<p><strong>2.5</strong> Names, logos, and other trademarks of S3 Stores may not be used apart from the documents or pages on which they appear and may not be used in any manner that implies affiliation with or endorsement by or disparages S3 Stores or other trademark owners. S3 Stores reserves the right to revoke such authorization at any time, and any such use shall be discontinued immediately upon written or electronic notice from S3 Stores.</p>\r\n<h2>3. Feedback</h2>\r\n<p><em>S3 Stores appreciates hearing from its users and welcomes your comments regarding S3 Stores products and services.</em></p>\r\n<h2>4. Disclaimer</h2>\r\n<p>The information, services, products and materials contained in this website are provided on an "as is" basis with no warranty. To the maximum extent permitted by applicable law, S3 Stores disclaims all representations and warranties, express or implied, with respect to such information, services, products and materials, including but not limited to warranties of merchantability, fitness for a particular purpose, non-infringement, freedom from computer virus or other harmful components, and implied warranties arising from course of dealing or course of performance. In addition, S3 Stores does not warrant that the information accessible via this website is current, complete, uninterrupted or error-free. Some countries do not allow the exclusion or limitation of implied warranties so the above limitation may not apply to you.</p>\r\n<h2>5. Limitation Of Liability</h2>\r\n<p>In no event will S3 Stores be liable for any loss of profit, loss of business, consequential, indirect, incidental, special or punitive damages, or for the cost of procurement of substitute goods and services, arising from your use or inability to use this site, or resulting from any goods or services purchased by you, even if S3 Stores has been advised of the possibility of such damages, whether in an action under contract, negligence or any other theory. Because some countries do not allow the exclusion or limitation of liability for consequential damages, the above limitation may not apply to you.</p>\r\n<h2>6. Indemnity</h2>\r\n<p><strong>6.1</strong> You agree to indemnify, defend and hold harmless S3 Stores and its associates, consultants, agents and suppliers from and against any and all claims, liability, damages and/or costs (including but not limited to reasonable legal fees) arising from your use of this website, the violation of these terms and conditions by you, or the infringement by you, or any other user of S3 Stores\' website through the use of your computer, or your infringement of any intellectual property or other right of any person or entity.</p>\r\n<p><strong>6.2</strong> S3 Stores reserves the right, at its own expense, to assume the exclusive defense and control of any matter otherwise subject to indemnification by you.</p>\r\n<h2>7. Governing Law &amp; Jurisdiction</h2>\r\n<p>These Terms of Service shall be governed by and construed in accordance with the laws of Canada. You agree that any legal action proceeding between you and S3 Stores relating to these Terms and Conditions of Use shall be brought exclusively before the Canadian judicial system.</p>\r\n<h2>8. Copyright &amp; Trademark Notices</h2>\r\n<p><strong>8.1</strong> The trademarks, logos and copyrights displayed on this website are the property of S3 Stores or other third parties.</p>\r\n<p><strong>8.2</strong> You are not permitted to use the trademarks, logos or copyrights without the prior written consent of S3 Stores or the third party that may own it.</p>\r\n<p><strong>8.3</strong> The name "S3 Stores" may not be used in connection with any product or service that is likely to cause confusion among customers, or in any manner that disparages or discredits S3 Stores.</p>\r\n<h2>9. Miscellaneous</h2>\r\n<p><strong>9.1</strong> These Terms and Conditions of Use constitute the entire agreement between you and S3 Stores with respect to this website and supersede and replace all prior or contemporaneous understandings or agreements, written or oral, regarding this website.</p>\r\n<p><strong>9.2</strong> S3 Stores\' failure to insist upon or enforce strict performance of any provision of these Terms and Conditions of Use shall not be construed as a waiver of any provision or right of S3 Stores. These Terms and Conditions of Use shall inure to the benefit of S3 Stores\'s successors and assigns.</p>\r\n</div>', NULL, 0),
  (3, NULL, 2, 1, 2, 1, 1, 0, 'Privacy policy', 'privacy-policy', NULL, 'page_2column.tpl', NULL, NULL, '2017-07-19 08:32:59', '2017-08-08 09:19:43', '2017-07-19 08:32:59', '<p>This privacy policy discloses the privacy practices for S3 Stores, Inc. websites.</p>\r\n<p>We take our obligations with regard to your personal information seriously, and have created this privacy policy to inform you of the information gathering and dissemination practices of this website. In wishing to demonstrate our commitment to your privacy, we have agreed to disclose our information-collecting practices and to notify you of:</p>\r\n<ol>\r\n<li>what personally identifiable information (or third party personally identifiable information) of yours is collected from you through our website</li>\r\n<li>the organization collecting the information</li>\r\n<li>how the information is used</li>\r\n<li>with whom the information may be shared</li>\r\n<li>what choices are available to you regarding collection, use and distribution of the information</li>\r\n<li>the kind of security procedures that are in place to prevent the loss, misuse or alteration of information under S3 Stores, Inc. control</li>\r\n<li>how you can correct any inaccuracies in the information.</li>\r\n</ol>\r\n<p>If you feel that S3 Stores, Inc. is not abiding by its posted privacy policy, please contact us.</p>\r\n<h2>Information Collection and Use</h2>\r\n<p>S3 Stores, Inc. is the sole owner of the information we collect on this site. We will not sell, share, or rent this information to others in ways different from what is disclosed in this policy statement. S3 Stores, Inc. collects information from our users at several different points on this website.</p>\r\n<h2>Membership</h2>\r\n<p>When you make a purchase on our website, you choose to become a member. You provide the following information to S3 Stores, Inc.:</p>\r\n<ul>\r\n<li>Your name</li>\r\n<li>Your email address</li>\r\n<li>Your billing and shipping address</li>\r\n<li>Your telephone number</li>\r\n<li>Your form of payment</li>\r\n<li>You choose your own member identification and password to use for all future purchases on the site.</li>\r\n<li>You choose whether or not you would like to receive electronic mailings from S3 Stores, Inc.</li>\r\n</ul>\r\n<h2>Ordering</h2>\r\n<p>We request information from the user on our order form when making a purchase. Here, a user must provide his/her contact and other information, (name and shipping address, shipping information, and form of payment). This information is used for billing purposes and to fill the customer\'s order. If we have difficulty processing an order, this contact information is used to get in touch with the customer.</p>\r\n<h2>Sharing</h2>\r\n<p>S3 Stores, Inc. does not share your private information with other companies. However, we may use an outside shipping company to ship orders, and use a credit card processing company to bill users for goods and services. These companies do not retain, share, store or use personally identifiable information for any secondary purposes. These companies may collect additional information if needed to provide you with the requested services.</p>\r\n<h2>Cookies</h2>\r\n<p>S3 Stores, Inc. sites employ web browser cookies. A cookie is a piece of data stored on the user\'s hard drive containing information about the user. S3 Stores, Inc. uses cookies to identify your visit session for customizing your user experience, for creating web site analytical data, and for Google Display Advertising and Remarketing with Google AdWords on third party websites. We use both session and persistent cookies. The website visitor may use features of their web browser to block or delete S3 Stores, Inc. cookies, cookies used for Google AdWords, and/or cookies used for Google Display Advertising and Remarketing with Google Adwords from the user\'s hard drive or memory. However, by disabling cookies, certain site features and functionality may no longer work properly, and the user may not see advertising on third party websites with reminders and special offers. You can opt out of Google Display Advertising and Remarketing with Google Adwords by visiting their <a href="https://support.google.com/ads/answer/2662922?hl=en/" target="_blank" rel="noopener noreferrer">website</a> and following the instructions presented on the page.</p>\r\n<h2>Usage Tracking</h2>\r\n<p>S3 Stores, Inc. database tracks the traffic throughout our site. This information is used to compile overall statistics and is not recorded at an individual level. This includes IP (internet protocol) addresses, browser type, ISP (internet service provider), referring/exit pages, platform type, date/time stamp, and # of clicks to analyze trends, administer the site, and track user movement in the aggregate. The statistics help us decide which products and services best serve our guests.</p>\r\n<h2>Aggregate Information</h2>\r\n<p>S3 Stores, Inc. uses aggregate information from demographic surveys, traffic patterns and IP addresses to customize our site. Aggregate information is occasionally shared with partners of S3 Stores, Inc. to plan advertising or promotions. We do not share any personally identifiable information.</p>\r\n<h2>Surveys</h2>\r\n<p>S3 Stores, Inc. may conduct surveys and other studies of its user base and make use of the results for marketing and planning purposes. Participation in such surveys is at the user\'s option. We reserve the right to disclose information provided by any user through a survey, provided that no personal information identifying that user is disclosed. Circumstances under which S3 Stores, Inc. would publicly disclose aggregate information include, but are not limited to, sharing survey results with partners and/or site users, business planning, and publicizing overall usage data in press communications.</p>\r\n<h2>Newsletters, Catalogs, Etc.</h2>\r\n<p>From time to time users may be given the opportunity to "opt-in" to receive site notifications, newsletters, or other information via email. Users may remove themselves from such services at their discretion. Any email sent to an "opt-in" list will include directions for how a user may remove himself or herself from the list, or a URL where the user may find such directions. If a user wishes to subscribe to our newsletter, catalog, etc., we ask for contact information such as name, street address and email address to provide these communications. Out of respect for our users\' privacy we provide ways to opt-out of these communications.</p>\r\n<p>On rare occasions it is necessary to send out a strictly service-related announcement. For instance, if our service is temporarily suspended for maintenance we might send you an email. Generally, users may not opt-out of these communications, though you can deactivate your account. However, these communications are not promotional in nature.</p>\r\n<h2>Tell-A-Friend</h2>\r\n<p>If a user elects to use our referral service for informing a friend about us or an item on our site, we ask them for the friend\'s name and email address. S3 Stores, Inc. will automatically send the friend a one-time email inviting them to visit the site. We do store the friend\'s email and they have an option to opt-out in the communication.</p>\r\n<h2>Special Request Pages</h2>\r\n<p>Our customers can use our special request pages to inquire about products that they cannot find on the website, for special orders for example. Personal information is gathered during this process, and is used strictly for the purposes of replying to user inquiries, billing purposes and to fill customers\' orders.</p>\r\n<h2>Correcting/Updating/Deleting/Deactivating</h2>\r\n<p>If a user\'s personally identifiable information changes (such as your phone, email or address), or if a user no longer desires our services, we offer ways to correct, update or delete/deactivate that user\'s personally identifiable information provided to us.</p>\r\n<h2>Links</h2>\r\n<p>This website contains links to other sites, whether owned or controlled by S3 Stores, Inc., or unrelated third parties. Please be aware that the privacy policies of those sites may differ from those of S3 Stores, Inc., and that we are not responsible for the privacy practices of these sites. We encourage our users to be aware when they leave our site and to read the privacy statements of every website that collects personally identifiable information. This privacy policy applies solely to information collected by S3 Stores, Inc.</p>\r\n<h2>Online Security</h2>\r\n<p>S3 Stores, Inc. takes every precaution to protect our users\' information. When users submit sensitive information via our website, we take steps to protect your information both online and offline. To secure site integrity, we employ measures, including but not limited to security audits, use of encryption tools and software, and other reasonable security measures and procedures.</p>\r\n<p>When a PayPal / 2CheckOut order form asks users to enter sensitive information (such as credit card number), that information is encrypted and is protected with the standard encryption software in the industry - Secure Socket Layers (SSLs). While on a secure page, such as our order form, a lock icon appears in your Web browser. When you are not on a secure page, no lock icon will appear.</p>\r\n<p>PayPal / 2CheckOut uses SSL encryption to protect sensitive information (like your credit card information) online.</p>\r\n<h2>Offline Security and Privacy</h2>\r\n<p>We do everything in our power to protect user information offline. All user information, not just the sensitive information mentioned above, is restricted in our offices. Only employees who need the information to perform a specific job (for example, our billing clerk or a customer service representative) are granted access to personally identifiable information. Our employees must use password-protected screen-savers when they leave their desk. When they return, they must re-enter their password to re-gain access to your information. Furthermore, all employees are fully informed about our security and privacy practices and are dutifully updated as new policies are added or revised. They are regularly notified and/or reminded about the importance we place on privacy, and what they can do to ensure that customers\' information is protected. Finally, the servers that we store personally identifiable information on are kept in a secure environment under restricted access.</p>\r\n<p>In the event that S3 Stores, Inc. becomes aware that site security is compromised or nonpublic user information has been disclosed to unrelated third parties as a result of external activity, including but not limited to external security attacks, we shall take reasonable measures which we deem appropriate, including but not limited to internal investigation and reporting, and notification to and cooperation with law enforcement authorities, notwithstanding other provisions of this Privacy Policy. If you have any questions about security on our websites, please contact us.</p>\r\n<h2>Privacy Policy Changes</h2>\r\n<p>In the event of any changes to S3 Stores, Inc. Privacy Policy, we will post the changes to this page and other places we deem appropriate, so that our users are always aware of what information we collect, how we use it, and under what circumstances, if any, we disclose it. We use information only in accordance with the privacy policy under which that information was collected.</p>\r\n<p>If at any time we plan on using your personally identifiable information in a manner different from that stated in this policy at the time of collection, we will notify you via email. You will have a choice to allow or disallow us to use your information in this manner. If you have opted out of all communication with the site, or deleted/deactivated your account, you will not be contacted, nor will your personal information be used in this new manner. In addition, if we make any material changes in our privacy practices that do not affect user information already stored in our database, we will post a prominent notice on our website notifying users of the change. In some cases where we post a notice we will also email users, who have opted to receive communications from us, notifying them of the changes in our privacy practices.</p>\r\n<p><em>Last modified: 8-19-13</em></p>', NULL, 0),
  (4, NULL, 3, 1, 2, 1, 1, 0, 'About Us', 'about-us', NULL, 'custom/about-us.tpl', NULL, NULL, '2017-07-20 05:15:16', '2017-08-09 08:14:45', '2017-07-20 05:15:16', '<h2>Mission statement</h2>\r\n<p>Quality tangible products in full taxonomy assortment delivered within estimated time frame and supported by professional customer service.</p>\r\n<h2>Who we are</h2>\r\n<p>Starting out as a small family-run online store selling professional quality art brushes, S3 Stores, Inc. expanded to carry a full line of professional artist supply products from large, well established and small artisan companies alike. Since then, we have expanded further to other specialties, among them office goods, supplies for teachers, products for various professionals, and more. We are an authorized dealer for all the product lines that we sell.</p>\r\n<h2>What we do</h2>\r\n<p>A direct connection with suppliers on a day-to-day basis, attention to customer needs, and years of experience allow us to offer top quality products at discount prices all at the touch of a button! All items are brand new and include manufacturers warranties, so you can buy with confidence. In all the areas in which we endeavor, our stores\' goal has been to carry the best known, globally established brands. At the same time, not forgetting our roots, we also strive to find for our customers the best of smaller, lesser known brands in each field. Our mission boils down to providing customers with top quality products, low prices, fast shipping, and a friendly, predictable, hassle-free shopping experience.</p>', NULL, 0),
  (5, NULL, 4, 1, 2, 1, 1, 0, 'S3 on Amazon', 's3-on-amazon', NULL, 'custom/on_amazon.tpl', NULL, NULL, '2017-07-20 08:16:01', '2017-08-08 09:20:50', '2017-07-20 08:16:01', NULL, NULL, 0),
  (6, NULL, 5, 1, 2, 1, 1, 0, 'Shipping & Delivery', 'shipping-delivery', NULL, 'page_2column.tpl', NULL, NULL, '2018-04-27 02:39:35', '2018-05-07 04:50:07', '2018-04-27 02:39:00', '<p>Purchases you make from S3 Stores are delivered to you via small-parcel carriers or LTL (less than truckload) freight carriers. Each is explained here.</p>\r\n<hr />\r\n<div class="large-2column">\r\n<p class="sd"><strong>Small Parcel:</strong></p>\r\n<ul>\r\n<li>Ground and 3-Day services will arrive via a small-parcel carrier such as UPS or FedEx</li>\r\n<li>A physical street address is required for all addresses, as we do not ship to P.O. boxes.</li>\r\n<li>Orders with an APO or FPO address can be processed only if the product lists availability for international shipping. These orders are shipped via USPS, for which there is often an additional charge.</li>\r\n</ul>\r\n<p class="sd">&nbsp;<strong>LTL Freight:</strong></p>\r\n<ul>\r\n<li>Products delivered using LTL Freight will arrive via a large truck from contracted freight carriers. Freight delivery is standard when the size and/or weight of the product is too large to ship using small-package carriers.</li>\r\n<li>LTL deliveries require a recipient to be present during delivery and are made during normal business hours Monday through Friday between 8 a.m. and 5 p.m. The delivery agent will call in advance to schedule a delivery appointment, generally within a 4-hour window. Alternatively, you can schedule your own appointment online with our carrier when tracking your shipment.</li>\r\n<li>LTL Deliveries are ground-floor deliveries made outside the main home entrance (e.g. inside a garage or to a front porch). Please note that the street/driveway of access must be at least 10 feet wide with an overhead clearance of at least 14 feet. If the street or driveway is smaller than this, additional handling charges may apply. Please contact our Customer Service department about availability and pricing for additional services.</li>\r\n<li>Transporting the item into the home or other area is the customer\'s responsibility. Individual drivers may provide some assistance, but S3 Stores cannot guarantee this additional service. Delivery agents are not equipped to dispose of packaging materials.</li>\r\n<li>Standard shipping rates for this type of delivery apply to the 48 Contiguous United States only. A physical street address is required for all addresses, as we do not ship to P.O. boxes.</li>\r\n</ul>\r\n<p class="sd"><strong>LTL Freight, Inside Delivery:</strong></p>\r\n<ul>\r\n<li>Inside Delivery is an upgrade service that includes special handling and placement. Products delivered using LTL Freight, Inside Delivery will arrive via a large truck from contracted freight carriers.</li>\r\n<li>Upon delivery, the service agent will place your product in the room of your choice. Removal of packaging material is not included with this service.</li>\r\n<li>Inside deliveries are made Monday through Friday between 8 a.m. and 5 p.m. and require a recipient to be present. The delivery agent will call in advance to schedule a delivery appointment, generally within a 4-hour window.</li>\r\n<li>The street/driveway of access must be at least 10 feet wide with an overhead clearance of at least 14 feet, with no vehicle weight restrictions.</li>\r\n<li>Stairways, doorways, hallways, and turns inside the premises should be at least 36 inches wide.</li>\r\n<li>The Inside Delivery service includes up to two normal flights of stairs (up to 15 steps each).</li>\r\n<li>Delivery conditions that are outside the above guidelines and those including but not limited to things such as sharp turns, narrow or gravel driveways, and gated communities or condominiums require additional handing services and fees. If any of these apply to your situation please contact our Customer Service department about availability/pricing for additional services.</li>\r\n<li>Standard shipping rates for this type of delivery apply to the 48 Contiguous United States only. A physical street address is required for all addresses, as we do not ship to P.O. boxes.</li>\r\n</ul>\r\n<p class="sd-green"><strong> Shipping Claims</strong></p>\r\n<p class="sd-green-mini"><img class="sd-green-img" src="/static/frontend/images/pages/Warning.png" /><strong>Please inspect your packages at the time of delivery and before you sign the carrier\'s delivery receipt.</strong></p>\r\n<p>&nbsp;</p>\r\n<p class="sd"><strong>Are all pieces accounted for?</strong></p>\r\n<p class="sd-normal-text">Please check that all items are correct and all pieces accounted for before you sign for a delivery. If a box is missing, you may accept the delivered pieces, but be sure make a note of the shortage on the delivery receipt, and contact our customer service team to locate the missing item(s).</p>\r\n<p>&nbsp;</p>\r\n<p class="sd"><strong>Are the boxes or product(s) damaged?</strong></p>\r\n<ul>\r\n<li>You may choose to refuse the delivery if there is damage to your item(s). If you choose to refuse the delivery, you must note the damages on the delivery receipt. Please contact our Customer Service department to notify us of the refusal.</li>\r\n<li>If only part of an item is damaged, you may accept the order, record the damages on the carrier\'s delivery receipt, and contact us. We may be able to replace damaged pieces. If a damaged item arrives outside of our business hours, please contact us the next business day. We will ensure that any replacement item(s) are sent to you promptly and free of charge.</li>\r\n<li>Once you have signed the delivery receipt indicating any notes on damage, be sure to ask the freight carrier for a copy of the delivery receipt. Also, record the freight company\'s name and truck number if possible so that we may track the order back to our vendor or warehouse.</li>\r\n<li>If you discover damages after the delivery is made, please contact our Customer Service department within 24 hours so that we may resolve the situation immediately.</li>\r\n</ul>\r\n<div class="sd-red-block">\r\n<p class="sd"><strong>Additional Notes:</strong></p>\r\n<ul>\r\n<li>Free shipping offers if available are listed on the product pages.</li>\r\n<li>S3 Stores works with hundreds of warehouses in the USA and Canada.</li>\r\n<li>Canadian Customers, <a href="https://www.crossbordershopping.ca/calculators/canadian-duty-calculator">click here to estimate the total cost of importing an item from the USA into Canada.</a> Please note that S3 Stores cannot be held responsible for discrepancies between this estimate and the actual charges.</li>\r\n<li>Shipping costs and delivery times are subject to change without notice.</li>\r\n<li>We try our best to calculate shipping charges accurately. Nonetheless additional shipping charges may apply. In such cases our customer service staff will contact you to confirm final shipping costs and order total before the order is shipped.</li>\r\n</ul>\r\n</div>\r\n</div>', NULL, 0),
  (7, NULL, 6, 1, 2, 1, 1, 0, 'Sales Taxes', 'sales-taxes', NULL, 'page_2column.tpl', NULL, NULL, '2018-04-27 07:32:29', '2018-05-07 06:48:24', '2018-04-27 07:32:00', '<div class="large-2column"><img class="st-tax-map" src="/media/Editor/sales-tax-map.png" alt="Sales tax map" width="588" height="608" />\r\n<div class="st-main-content">\r\n<p>Our company is incorporated in Ontario, Canada. US and international customers are not charged any sales taxes.</p>\r\n<p class="st-war-txt"><img class="st-war-img" src="/media/Editor/Warning.png" alt="" width="37" height="36" />Sales taxes only apply to sales made to Canadian residents.</p>\r\n<p class="st-descr">The following sales taxes will be automatically applied to purchases from these provinces:</p>\r\n<table class="st-per-all">\r\n<tbody>\r\n<tr>\r\n<td class="st-td-name">Alberta</td>\r\n<td class="st-per-blue">5% GST</td>\r\n</tr>\r\n<tr>\r\n<td class="st-td-name">British Columbia</td>\r\n<td class="st-per-blue">5% GST</td>\r\n</tr>\r\n<tr>\r\n<td class="st-td-name">Manitoba</td>\r\n<td class="st-per-blue">5% GST</td>\r\n</tr>\r\n<tr>\r\n<td class="st-td-name">New Brunswick</td>\r\n<td class="st-per-yellow">13% HST</td>\r\n</tr>\r\n<tr>\r\n<td class="st-td-name">Newfoundland and Labrador</td>\r\n<td class="st-per-yellow">13% HST</td>\r\n</tr>\r\n<tr>\r\n<td class="st-td-name">Northwest Territories</td>\r\n<td class="st-per-blue">5% GST</td>\r\n</tr>\r\n<tr>\r\n<td class="st-td-name">Nova Scotia</td>\r\n<td class="st-per-red">15% HST</td>\r\n</tr>\r\n<tr>\r\n<td class="st-td-name">Nunavut</td>\r\n<td class="st-per-blue">5% GST</td>\r\n</tr>\r\n<tr>\r\n<td class="st-td-name">Ontario</td>\r\n<td class="st-per-yellow">13% HST</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>', NULL, 0),
  (8, NULL, 7, 1, 2, 1, 1, 0, 'Safe & Secure Shopping', 'safe-and-secure-shopping', NULL, 'safe_secure.tpl', NULL, NULL, '2018-04-28 02:01:42', '2018-05-03 05:56:32', '2018-04-28 02:01:00', '<div class="large-2column">\r\n<p>When you shop at S3 Stores, you never have to worry about the status of your personal information, including credit card safety. We guarantee that every transaction you make on our site is safe and secure.</p>\r\n<p>S3 Stores uses Secure Sockets Layer (SSL), the standard encryption technology for online commercial transactions, on pages where you need to enter personally identifiable information, ensuring that only S3 Stores can read your personal information. Unlike other companies, we do not store your credit card information on our servers. When you see a green padlock icon in the address bar of your browser window, you are on a secure page.</p>\r\n<p>Online purchases are statistically safer than using your credit card at a restaurant or&nbsp;department store. Credit card security experts note that online purchases are far safer than traditional credit card transactions because the information is immediately encrypted into a scrambled message that can only be decrypted by an authorized computer. Under the Fair Credit Billing Act, your bank cannot hold you liable for more than $50.00 of fraudulent charges. For your peace of mind, if your bank does hold you liable for any of this $50.00, we will cover the entire liability for you, up to the full $50.00. We will only cover this liability if the unauthorized use of your credit card resulted through no fault of your own from purchases made at S3 Stores while using a secure server.</p>\r\n<p>In the event of unauthorized use of your credit card, you must notify your credit card provider in accordance with its reporting rules and procedures.</p>\r\n</div>', NULL, 0),
  (9, NULL, 8, 1, 2, 1, 1, 0, 'Return Policy', 'return-policy', NULL, 'return_policy.tpl', NULL, NULL, '2018-05-04 02:55:20', '2018-05-04 03:03:04', '2018-05-04 02:55:00', '<div class="large-2column">\r\n<ol>\r\n<li>If the box or/and merchandise you receive is damaged in any way, you must reject it or immediately report damage to the delivery company.<br /><br /><strong>We will not provide credit for the merchandise damaged in transit if the damage was not reported to the delivery company on the spot.<br /><br /></strong></li>\r\n<li>We want you to be absolutely satisfied with your purchase. A return for any reason must be requested in writing and sent to rma@s3stores.com within 14 days of receiving the product.<br /><br /><strong>All return claims made after 14 days of receiving the product will be rejected.<br /><br /></strong></li>\r\n<li>A return must first be approved by our RMA (return merchandise authorization) department. If product return is approved, our RMA department will send you an RMA form and return instructions by email.<br /><br /><strong>No credits will be given for unauthorized returns (product returns with missing RMA form).<br /><br /></strong></li>\r\n<li>S3 Stores will take responsibility for merchandise that is defective or sent in error provided that the problem was reported within 14 days of receiving the product. RMA returns for any other reason will incur a minimum 25% restocking fee, in addition, S3 Stores will not be held responsible for return shipping charges. S3 Stores will not accept even RMA returns shipped C.O.D. or collect.</li>\r\n</ol>\r\n</div>', NULL, 0),
  (10, NULL, 9, 1, 2, 1, 1, 0, 'Retrieve Orders', 'retrieve-orders', NULL, 'retrieve_orders.tpl', NULL, NULL, '2018-05-04 03:49:18', '2018-05-04 05:24:45', '2018-05-04 03:49:00', '<p><strong>To access your order history, please enter the email address used during your last purchase. Your invoice(s) will be emailed to you immediately. If you do not receive an email from us within 5 minutes, please check your SPAM folder.</strong></p>', NULL, 0),
  (11, NULL, 10, 1, 2, 1, 1, 0, 'Order Communication', 'order-communication', NULL, 'page.tpl', NULL, NULL, '2018-05-10 05:34:26', '2018-05-10 05:34:26', '2018-05-10 05:34:26', '<p><br />If you\'ve already placed the order, please send emails to<br /><a href="mailto:helpdesk@s3stores.com">helpdesk@s3stores.com</a><br />and mention your order number (it has&nbsp;<strong><em>LL-NNNNN</em></strong>&nbsp;format, where&nbsp;<strong><em>L</em></strong>&nbsp;is a letter and&nbsp;<strong><em>N</em></strong>&nbsp;is a number) in the subject line to ensure correct routing.</p>', NULL, 0),
  (12, NULL, 11, 1, 2, 1, 1, 0, 'Combating eCommerce Fraud', 'combating-fraud', NULL, 'page.tpl', NULL, NULL, '2018-05-10 05:56:35', '2018-05-10 05:56:35', '2018-05-10 05:56:35', '<p><br />Ecommerce fraud is a serious crime, affecting online stores and honest customers alike. Among its various forms, frivolous chargebacks are often the main problem that merchants have to deal with. Frivolous chargebacks occur when a customer receives products, asks their credit card company for a refund, and keeps the goods. This is essentially a form of theft.<br /><br />S3 Stores takes frivolous chargebacks seriously. When faced with this problem, we collect all the necessary paperwork, including proof of delivery, and submit this information to local jurisdictions for investigation and prosecution. It is our policy to deal with cyber criminals to the fullest extent of the law.<br /><br />Although there may be valid grounds for a chargeback, we believe that most any problem can be resolved with the help of our Customer Service team without resorting to one.&nbsp;<br /><br />If you have any questions or concerns, please&nbsp;<a href="../help.php?section=contactus&amp;mode=update">contact us</a>.<br /><br /></p>', NULL, 0),
  (13, NULL, 12, 1, 2, 1, 1, 0, 'Backorder Policy', 'backorder-policy', NULL, 'page.tpl', NULL, NULL, '2018-05-10 05:58:08', '2018-05-10 05:58:08', '2018-05-10 05:58:08', '<p><br />When a product is labeled \'Temporarily Out of Stock\', the product is still available for order. It\'s currently not available in our warehouses, but we have ordered more from our suppliers. Most out of stock items are replenished within a few days. In some cases, production delays or inventory shortages may delay the arrival of your item to our fulfillment center.<br /><br />We ship from warehouses located across the United States and Canada. If you add a product that\'s out of stock to your shopping cart, it may hold up other items shipped from the same warehouse until the unavailable item arrives at our warehouse. Items shipped from other locations will not be affected. Add items to your cart, click \'Shipping quote\' and \'Calculate grand total\' to see which part of the order contains the temporarily out of stock item. We\'ll remind you on checkout about an out of stock item, and will send an email the moment the part of the order containing the item is on its way. If you don\'t want to wait, you can swap the out of stock item for something similar, or remove it from the order completely, either on checkout, or by&nbsp;<a href="../help.php?section=contactus&amp;mode=update">contacting</a>&nbsp;our customer service team.&nbsp;</p>', NULL, 0),
  (14, NULL, 13, 1, 2, 1, 1, 0, 'Shipping Claims', 'shipping-claims', NULL, 'page.tpl', NULL, NULL, '2018-05-10 05:59:13', '2018-05-10 05:59:13', '2018-05-10 05:59:13', '<p><br /><span style="color: red;">Please inspect your packages at the time of delivery and before you sign the carrier\'s delivery receipt.</span><br /><br /><strong>Are all pieces accounted for?</strong></p>\r\n<ul type="disc">\r\n<li>It is your responsibility to check that all items are correct and all pieces accounted for before you sign for a delivery. If a box is missing, you may accept the delivered pieces, but be sure make a note of the shortage on the delivery receipt, and contact our Customer Service team to locate the missing item(s).</li>\r\n</ul>\r\n<p><br /><strong>Are the boxes or product(s) damaged?</strong></p>\r\n<ul type="disc">\r\n<li>You may choose to refuse the delivery if there is damage to your item(s). If you choose to refuse the delivery, you must note the damages on the delivery receipt. Please contact our Customer Service department to notify us of the refusal.</li>\r\n<li>If only part of an item is damaged, you may accept the order, record the damages on the carrier\'s delivery receipt, and contact us. We may be able to replace damaged pieces. If a damaged item arrives outside of our business hours, please contact us the next business day. We will ensure that any replacement item(s) are sent to you promptly and free of charge.</li>\r\n<li>Once you have signed the delivery receipt indicating any notes on damage, be sure to ask the freight carrier for a copy of the delivery receipt. Also, record the freight company\'s name and truck number if possible so that we may track the order back to our vendor or warehouse.</li>\r\n<li>If you discover damages after the delivery is made, please contact our Customer Service department within 24 hours so that we may resolve the situation immediately.</li>\r\n</ul>', NULL, 0),
  (15, NULL, 14, 1, 2, 1, 1, 0, 'Money-Back Guarantee', 'money-back-guarantee', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:00:22', '2018-05-10 06:00:22', '2018-05-10 06:00:22', '<p><img src="../skin1_kolin/images/Static-pages/Money-Back-Guarantee/moneyback_guarantee.gif" alt="Money-Back Guarantee" />&nbsp;</p>\r\n<h1>Artist Supply Source, Inc. 30-Day Money-Back Guarantee:</h1>\r\n<ul>\r\n<li>All products being sold on this website are covered by 30-day unconditional money-back guarantee (shipping charge is not refundable)&nbsp;<br /><br /></li>\r\n<li>All product returns have to be authorized by us: Please contact us first&nbsp;<br /><br /></li>\r\n<li>Please contact us before sending us the return! We may send you a replacement product immediately&nbsp;<br /><br /></li>\r\n<li>Monetary refunds are issued within 2 business days after the product is received&nbsp;<br /><br /><em>In conclusion, we would like to mention that since we sell the highest quality art supplies the refund rate for our store is quite low (less than 1% of the total number of orders shipped).</em></li>\r\n</ul>', NULL, 0),
  (16, NULL, 15, 1, 2, 1, 1, 0, 'Special Offers', 'special-offers', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:01:30', '2018-05-10 06:01:30', '2018-05-10 06:01:30', '<p>We offer free shipping on artist/cosmetic brush orders over certain dollar amount. Please visit the&nbsp;<a class="SPItems" href="Shipping-Methods-sp-15.html">Shipping Methods page</a>&nbsp;for details.</p>', NULL, 0),
  (17, NULL, 16, 1, 2, 1, 1, 0, 'Purchase Orders', 'purchase-orders', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:02:24', '2018-05-10 06:02:24', '2018-05-10 06:02:24', '<p><br />Purchase orders from&nbsp;<strong>educational institutions and governmental bodies</strong>&nbsp;are welcome!<br /><br /><strong>Instructions:</strong><br />- On checkout, please choose "Purchase Order" as your payment method.<br />- Submit your order.<br />- Fax your organization\'s letterhead to us.<br />- Advise your accounting department to make out a check payable to&nbsp;<strong>S3 Stores, Inc.</strong><br /><br />All purchase orders are subject to verification.<br /><br /><em>Our W-9 form can be faxed or emailed to your organization upon request.</em><br /><br /></p>', NULL, 0),
  (18, NULL, 17, 1, 2, 1, 1, 0, 'Bill Me Later', 'bill-me-later', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:03:24', '2018-05-10 06:03:24', '2018-05-10 06:03:24', '<p><br />We offer a Bill Me Later payment method through PayPal.<br /><br /><strong>How does Bill Me Later work?</strong></p>\r\n<ul type="disc">\r\n<li>Check out with PayPal and choose Bill Me Later.</li>\r\n<li>Answer the two quick questions, read and accept the terms.</li>\r\n<li>Look for your Bill Me Later statement via email.</li>\r\n</ul>\r\n<p>&nbsp;</p>', NULL, 0),
  (19, NULL, 18, 1, 2, 1, 1, 0, 'Testimonials', 'testimonials', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:07:26', '2018-05-10 06:07:26', '2018-05-10 06:07:26', '<hr />\r\n<p><em>I recently received your shipment of brushes. I thought I would put them through a series of tests. Let me tell you what a surprise I had! They performed as well as my expensive Kolinsky sables. They held a great deal of paint, they maintained a point, the bristles had a bounce ... all the great qualities I look for in my brushes but at a fraction of the price. I will definitely recommend these brushes to my students. Thanks again, it\'s been a pleasure dealing with you.&nbsp;<br /><br /><strong>Carolyn R.</strong></em></p>\r\n<hr />\r\n<p><em>I was buying Windsor Newton sable brushes. Your brushes are better because they are stiffer and the sable does not fall out.&nbsp;<br /><br /><strong>Marvin Steel</strong></em></p>\r\n<hr />\r\n<p><em>Although I paint with acrylics, I use your brushes for some fine detailing. I just started using your brushes and I love them.&nbsp;<br /><br /><strong>Doreen T.</strong></em></p>\r\n<hr />\r\n<p><em>Please let me know when you restock the Kolinsky sable round brushes and I will order more. They have turned out to be excellent quality.&nbsp;<br /><br /><strong>Joseph D. Di V.</strong></em></p>\r\n<hr />\r\n<p><em>... I have some of your brushes and love them. I am a recreational painter and have created some lovely pots for plants as well as 2 canvases that I have hung and a third that a friend walked off with and has decided she wants as a Christmas present ...&nbsp;<br /><br /><strong>Glenda G.</strong></em></p>\r\n<hr />\r\n<p><em>This is to let you know that I received my brushes in record time; I was very impressed by the speed of the delivery. The quality is far superior to any brushes that I have ever used before and I look forward to hours of indulging in my favorite pastime. Thank you so much. Sincerely,&nbsp;<br /><br /><strong>Barbara J.</strong></em></p>\r\n<hr />\r\n<p><em>I just got the brushes and I love them -- they are wonderful -- thank you.&nbsp;<br /><br /><strong>David Louis Feinberg</strong></em></p>\r\n<hr />\r\n<p><em>Your art brushes arrived at my studio today. They are the best sables I ever saw, and came in perfect condition. Thank you for your kindnesses.&nbsp;<br /><br /><strong>Tadao Okazaki</strong></em></p>\r\n<hr />\r\n<p><em>I received my brushes yesterday. Thank you for your prompt and excellent service. I am very happy with the quality of the brushes. This was my second order! I will let others know that you sell high quality brushes at wholesale prices! Thanks again!&nbsp;<br /><br /><strong>Maria F.</strong></em></p>\r\n<hr />\r\n<p><em>I wanted to let you know my brushes arrived today and I am well pleased. Thank you for your prompt service.&nbsp;<br /><br /><strong>Joyce Ishee</strong></em></p>\r\n<hr />\r\n<p><em>I am not able to get good quality brushes at a reasonable price locally. Having your brushes available on the internet is a wonderful asset.&nbsp;<br /><br /><strong>John P. Barker</strong></em></p>\r\n<hr />\r\n<p><em>My introductory set of 5 Kolinsky brushes has just arrived. About a week or two sooner than I ever expected them to considering I live in Australia. I\'ve immediately tried the number 8 round and boy, does it pass the test. It\'s great!&nbsp;<br /><br /><strong>Sophia M.</strong></em></p>\r\n<hr />\r\n<p>I had never heard of your company. It came up under a google search when I used the words Sienna Pochade Box. I will be telling my artist friends of your company as you had the very best price, and because the price was lower I was able to purchase the large size pochade box instead of the medium. Also, the delivery was quick. I appreciated that! Thank you for excellent service!&nbsp;<br /><br /><strong><em>Tami D.</em></strong></p>\r\n<hr />', NULL, 0),
  (20, NULL, 19, 1, 2, 1, 1, 0, 'Community', 'community', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:19:37', '2018-05-10 06:19:37', '2018-05-10 06:19:37', '<p><br />Help us grow, tell your friends and colleagues about us!<br /><br /></p>\r\n<table cellpadding="6">\r\n<tbody>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td colspan="2"><iframe src="http://www.youtube.com/embed/videoseries?list=PL97381D1B28B1418D&amp;hl=en_US" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-mce-src="http://www.youtube.com/embed/videoseries?list=PL97381D1B28B1418D&amp;hl=en_US" data-mce-fragment="1"></iframe></td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, 0),
  (21, NULL, 20, 1, 2, 1, 1, 0, 'Our Price Guarantee', 'our-price-guarantee', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:21:04', '2018-05-10 06:21:04', '2018-05-10 06:21:04', '<p><br />S3 Stores is a leader in online retail pricing. We are constantly on the lookout for new ways to bring you the very best prices in the industry, all without a loss of quality in the products and services we offer. Shopping with us, you\'ll find that the more you order, the more you save, on merchandise as well as on shipping.&nbsp;<br /><br />S3 Stores fully complies with Minimum Advertised Pricing (MAP) standards enforced by brand owners. All MAP violations should be reported to&nbsp;<a href="mailto:map@s3stores.com">map@s3stores.com</a>.&nbsp;<br /><br /></p>', NULL, 0),
  (22, NULL, 21, 1, 2, 1, 1, 0, 'Retail Trust terms and conditions', 'retail-trust-terms-and-conditions', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:22:32', '2018-05-10 06:22:32', '2018-05-10 06:22:32', '<p><a style="display: inline-block; width: 200px; height: 40px; margin: 0 auto;" title="RetailTrust"><img id="retail_logo" style="margin: 0px auto; padding: 0px; display: block;" src="../skin1_kolin/images/mail/retail_trust/img/logo.svg" alt="" width="200" height="40" /></a></p>\r\n<p style="text-align: center;"><span style="font-size: medium;"><strong><span style="font-family: verdana, geneva;">Terms &amp; Conditions</span></strong></span></p>\r\n<p style="text-align: justify;"><span style="font-family: verdana, geneva; font-size: small;"><strong>Definitions</strong>:</span></p>\r\n<p style="text-align: justify;"><span style="font-family: verdana, geneva; font-size: small;"><em>Service</em>&nbsp;&ndash; means the Retail Trust service presented at all the stores of S3Stores, Inc.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: verdana, geneva; font-size: small;"><em>Service sign</em>&nbsp;&ndash; means the logo of Retail Trust service, presented in several product pages.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: verdana, geneva; font-size: small;"><em>Service refund</em>&nbsp;&ndash; 100% of the item(s) cost, excluding the Service price.</span></p>\r\n<ol style="text-align: justify;">\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">This Service provides you with an option of returning products you purchased from S3Stores, Inc. during 3 months (90 ongoing days) after the purchase date. You must meet the conditions in this list in order to get a refund.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">Only products where the Service sign presented are eligible for buying this service.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">If you buy a set of products or several products of the same type, then buying the Service will mean that whole set is the subject of the Service.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva;"><span style="font-size: small;">We will accept:</span></span>\r\n<ul>\r\n<li style="margin: 5px 0;"><span style="font-size: small;">Product in re-sellable condition with original package, documents and accessories.</span></li>\r\n</ul>\r\n</li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">We will not accept:</span>\r\n<ul style="text-align: justify;">\r\n<li style="margin: 5px 0;"><span style="font-family: verdana, geneva; font-size: small;">Products that were intentionally damaged;</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">Lost, stolen, irretrievable items;</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">Product(s) that is fraudulently described or materially misrepresented</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">Product(s) with removed or altered serial numbers;</span></li>\r\n<li><span style="font-family: verdana, geneva; font-size: small;">Maintenance, repair, or replacement necessitated by loss or damage resulting from any cause other than normal use and operation of the product in accordance with the manufacturer\'s specifications and owner\'s manual, including, but not limited to, exposure to weather conditions, failure to properly clean, maintain or lubricate, operator negligence, misuse, abuse, improper electrical/power supply, improper equipment modifications, attachments or installation or assembly, vandalism, animal or insect infestation, battery leakage, act of nature (any accident caused or produced by any physical cause which cannot be foreseen or prevented, such as storms, perils of the sea, tornadoes, hurricanes, floods and earthquakes), or any other peril originating from outside the product;</span></li>\r\n</ul>\r\n</li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">Products sold as set of several items or Product purchased as set of several identical items must be shipped back in the same amount.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">If you want to cancel this service for any reason you will receive a pro rata refund based on the time remaining on your Service.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">If the product shipped to you is already damaged or in non-operational condition we will replace it with the new one, no additional charges.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">Any controversy or claim arising out of or relating to this Service, or breach thereof, will be settled by binding arbitration in accordance with the Commercial Arbitration Rules of the American Arbitration Association. Under this Arbitration provision, we both give up the right to resolve any controversy or claim arising out of or relating to this Protection Plan by a judge and/or a jury. Prior to filing any arbitration, we jointly agree to seek to resolve any dispute between us by mediation conducted by the AAA, with all mediator fees and expenses paid by us. If you are successful in obtaining an arbitration award against us greater than $500, we agree to pay all arbitrator fees and expenses.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">We may cancel this Service at our opinion on the basis of fraud or material misrepresentation by you.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">If customer wants to return the purchased product and get a refund then customer must send purchased product(s) back on at his/her own expense.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">Customer enquiries are accepted with e-mail notification or a phone call to any of phone numbers presented on every store&rsquo;s pages.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">S3 Stores, Inc. customer service representative has the right to ask the client for a formal reason of return and a photo of the item.</span></li>\r\n<li style="margin-bottom: 10px;"><span style="font-family: verdana, geneva; font-size: small;">The service provides you only a return of the products cost, not replacement.</span></li>\r\n</ol>', NULL, 0),
  (23, NULL, 22, 1, 2, 1, 1, 0, 'Affiliate Program', 'affiliate-program', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:23:54', '2018-05-10 06:23:54', '2018-05-10 06:23:54', '<p>Are you a webmaster, blogger, email list owner, social media influencer or any type of Internet based web publisher? Now you can earn a great commission from your referral traffic by sending you visitors to the ArtistSupplySource.com website.</p>\r\n<h2>Artist Supply Source Affiliate Program Features</h2>\r\n<ul>\r\n<li>FREE to join</li>\r\n<li>Sale Commission Rate is 7% for all products</li>\r\n<li>No Tracking Gap</li>\r\n<li>Thousands of products</li>\r\n<li>Free ready to use banners</li>\r\n<li>High conversion rate</li>\r\n</ul>\r\n<h2>Get Links, Buttons or Banners for Your Site</h2>\r\n<p>Artist Supply Source works with the top affiliate network&nbsp;<a href="https://www.shareasale.com/" target="_blank" rel="noopener noreferrer">ShareASale</a>. This network offers a simple affiliate signup process, so you can begin earning commission payments as soon as possible.</p>\r\n<p>Sign up today and start earning at&nbsp;<a href="http://www.shareasale.com/join/69373" target="_blank" rel="noopener noreferrer">ShareASale</a>&nbsp;with Artist Supply Source!</p>\r\n<ol>\r\n<li>At ShareASale you can use banners or links to promotion. Learn more about ShareASale&rsquo;s linking tool&nbsp;<a href="http://blog.shareasale.com/2014/05/01/best-practices-for-creating-a-custom-link/" target="_blank" rel="noopener noreferrer">here</a>.</li>\r\n<li>You can also use a tool called&nbsp;<a href="https://www.inlinkz.com/new/index.php" target="_blank" rel="noopener noreferrer">InLinkz</a>. Watch the&nbsp;<a href="https://www.youtube.com/watch?v=oACrDtNPmYw" target="_blank" rel="noopener noreferrer">video</a>&nbsp;about making your affiliate links using InLinkz Link Manager.</li>\r\n</ol>\r\n<div style="text-align: center;"><a class="join-us" style="line-height: 1; font-size: 1em !important; font-weight: bold; display: inline-block; color: #ffffff !important; text-decoration: none !important; text-transform: uppercase; padding: 0.775em 2em 0.775em 2em; outline: none; border: 1px solid #ffffff; border-radius: 6px; background: linear-gradient(#ffc321, #ff9000) #ffc321; transition: 0.2s;" href="http://www.shareasale.com/join/69373" target="_blank" rel="noopener noreferrer">JOIN US</a></div>', NULL, 0),
  (24, NULL, 23, 1, 2, 1, 1, 0, 'Jobs', 'ac-jobs', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:25:27', '2018-05-10 06:26:21', '2018-05-10 06:25:00', '<p>&nbsp;</p>\r\n<h2 dir="ltr">At S3 Stores, we&rsquo;re always looking for bright and curious people to become a part of our team. If you&rsquo;re looking for an interesting and challenging career, welcome aboard!</h2>\r\n<h2 dir="ltr">Content Marketer / SEO Copywriter (Healthcare) - Freelance</h2>\r\n<p dir="ltr">Responsibilities:</p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">Writing copy for e-commerce and web production teams (including editorial features and website landing pages)</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Writing on the website blog (original articles on relevant topics, 700-3000 words)</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Collaborating with SEO team to optimize copy and identify trends</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Writing and maintaining standards for e-commerce copy based on readability scores</p>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p dir="ltr">Requirements/Qualifications:</p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">3rd year of Bachelor program or higher</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">English native or fluent English speaker (certification in language proficiency for non-native speakers will be an advantage)</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Excellent prioritization and organization skills</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">An entrepreneurial spirit, and ability to think critically about digital strategy and opportunities</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Ability to edit copy with a practiced eye</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Passion for medicine/ healthcare and related subjects</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Close acquaintance with Chicago Manual of Style</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">A strong love for writing</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Experience in working with blogging platforms (Wordpress, Squarespace, Hubspot, etc.)</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Desire to always improve and perfect the final product and oneself</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Self-motivation, self-awareness, good judgment, positive attitude and willingness to support your team</p>\r\n</li>\r\n</ul>\r\n<p><br />If you have any questions or want to send your CV, please, contact us at&nbsp;<a href="mailto:job@s3stores.com">job@s3stores.com</a></p>\r\n<p>&nbsp;</p>', NULL, 0),
  (25, NULL, 24, 1, 2, 1, 1, 0, 'Jobs', 'ar-jobs', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:26:07', '2018-05-10 06:26:07', '2018-05-10 06:26:07', '<p>&nbsp;</p>\r\n<h2 dir="ltr">At S3 Stores, we&rsquo;re always looking for bright and curious people to become a part of our team. If you&rsquo;re looking for an interesting and challenging career, welcome aboard!</h2>\r\n<h2 dir="ltr">Content Marketer / SEO Copywriter (Art &amp; Craft) - Freelance</h2>\r\n<p dir="ltr">Responsibilities:</p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">Writing copy for e-commerce and web production teams (including editorial features and website landing pages)</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Writing on the website blog (original articles on relevant topics, 700-3000 words)</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Collaborating with SEO team to optimize copy and identify trends</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Writing and maintaining standards for e-commerce copy based on readability scores</p>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p dir="ltr">Requirements/Qualifications:</p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">3rd year of Bachelor program or higher</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">English native or fluent English speaker (certification in language proficiency for non-native speakers will be an advantage)</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Excellent prioritization and organization skills</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">An entrepreneurial spirit, and ability to think critically about digital strategy and opportunities</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Ability to edit copy with a practiced eye</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Passion for fine art, craft and related subjects</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Close acquaintance with Chicago Manual of Style</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">A strong love for writing</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Experience in working with blogging platforms (Wordpress, Squarespace, Hubspot, etc.)</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Desire to always improve and perfect the final product and oneself</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Self-motivation, self-awareness, good judgment, positive attitude and willingness to support your team</p>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p dir="ltr">If you have any questions or want to send your CV, please, contact us at&nbsp;<a href="mailto:job@s3stores.com">job@s3stores.com</a></p>', NULL, 0),
  (26, NULL, 25, 1, 2, 1, 1, 0, 'Fellowship', 'fellowship-ar', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:27:28', '2018-05-10 06:27:28', '2018-05-10 06:27:28', '<p style="text-align: left;">&nbsp;</p>\r\n<p dir="ltr" style="text-align: center;"><strong>S3 Fellowship Award for Art &amp; Design Students</strong></p>\r\n<p>&nbsp;</p>\r\n<p dir="ltr"><strong>Award Amount:</strong>&nbsp;$1,000 annually, non-renewable.</p>\r\n<p dir="ltr"><strong>Recipients:</strong>&nbsp;One award offered annually.</p>\r\n<p dir="ltr"><strong>Eligibility:</strong></p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">Must be a full-time student.</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Must be enrolled in a college or university during the academic year following the deadline date.</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Must be pursuing a degree in art, design or a related field.</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Must be enrolled in college or university in the U.S. and Canada.</p>\r\n</li>\r\n</ul>\r\n<p dir="ltr"><strong>Additional Information:</strong></p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">The winner will be selected from the submitted essays.</p>\r\n</li>\r\n</ul>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">Past scholarship recipients are allowed to reapply.</p>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p dir="ltr"><strong>Deadline:</strong>&nbsp;Sunday, April 1, 2018. &nbsp;A decision will be announced May 1, 2018.</p>\r\n<p dir="ltr"><strong>Deadline Information:</strong></p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">Students must first complete the application form and send an essay of 1-2 pages on the topic of&nbsp;<span style="text-decoration: underline;"><em>&lsquo;Your Most Significant Art or Craft Project&rsquo;</em></span>.</p>\r\n</li>\r\n<li>The winner will be required to submit an email, including the following documentation: a recent resume or CV, an enrollment verification letter, two letters of recommendation.</li>\r\n</ul>\r\n<p><em>Contact Information:</em>&nbsp;fellowship@s3stores.com</p>\r\n<p><em>Fill In The Application Form:</em>&nbsp;<a href="https://goo.gl/jfJmbz">Click Here</a></p>', NULL, 0),
  (27, NULL, 26, 1, 2, 1, 1, 0, 'Fellowship', 'fellowship-ac', NULL, 'page.tpl', NULL, NULL, '2018-05-10 06:28:22', '2018-05-10 06:28:22', '2018-05-10 06:28:22', '<p>&nbsp;</p>\r\n<p dir="ltr" style="text-align: center;"><strong>S3 Fellowship Award for Medical, Nursing &amp; Pharmacy Students</strong></p>\r\n<p>&nbsp;</p>\r\n<p dir="ltr"><strong>Award Amount:</strong>&nbsp;$1,000 annually, non-renewable.</p>\r\n<p dir="ltr"><strong>Recipients:</strong>&nbsp;One award offered annually.</p>\r\n<p dir="ltr"><strong>Eligibility:</strong></p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">Must be a full-time student.</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Must be enrolled in a medical, nursing or pharmacy school during the academic year following the deadline date.</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Must be pursuing a degree in healthcare, medicine or a related field.</p>\r\n</li>\r\n<li dir="ltr">\r\n<p dir="ltr">Must be enrolled in medical schools in the U.S. and Canada.</p>\r\n</li>\r\n</ul>\r\n<p dir="ltr"><strong>Additional Information:</strong></p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">The winner will be selected from the submitted essays.</p>\r\n</li>\r\n</ul>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">Past scholarship recipients are allowed to reapply.</p>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p dir="ltr"><strong>Deadline:</strong>&nbsp;Sunday, April 1, 2018. &nbsp;A decision will be announced May 1, 2018.</p>\r\n<p dir="ltr"><strong>Deadline Information:</strong></p>\r\n<ul>\r\n<li dir="ltr">\r\n<p dir="ltr">Students must first complete the application form and send an essay of 1-2 pages on the topic of&nbsp;<span style="text-decoration: underline;"><em>&lsquo;The Most Important Medical Invention&rsquo;</em></span>.</p>\r\n</li>\r\n<li>The winner will be required to submit an email, including the following documentation: a recent resume or CV, an enrollment verification letter, two letters of recommendation.</li>\r\n</ul>\r\n<p><em>Contact information:&nbsp;</em>fellowship@s3stores.com</p>\r\n<p><em>Fill In The Application Form:</em>&nbsp;<a href="https://goo.gl/Q7iYEQ" target="_blank" rel="noopener noreferrer">Click Here</a></p>', NULL, 0);

INSERT INTO `xcart_payment_processor` (`processor_id`, `processor_name`, `transaction_link`, `param01`, `param02`, `test_mode`) VALUES (3, 'Offline', '', NULL, NULL, 'N');
INSERT INTO `xcart_payment_processor` (`processor_id`, `processor_name`, `transaction_link`, `param01`, `param02`, `test_mode`) VALUES (4, 'Xpay', '', NULL, NULL, 'N');

ALTER TABLE `xcart_payment_methods`
  ADD COLUMN `frontend_processor_id` INT(11) NULL DEFAULT NULL AFTER `processor_id`;

UPDATE `xcart_orders`
SET cart_number = null;
ALTER TABLE `xcart_orders`
  DROP INDEX `cart_number`,
  ADD UNIQUE INDEX `cart_number` (`cart_number`);

Update pages_page as p Set p.url = 'ecomerce-fraud'
Where p.name = 'Combating eCommerce Fraud';

ALTER TABLE `order_extra`
  ADD COLUMN `ip` VARCHAR(255) NULL DEFAULT NULL COMMENT 'Customer IP' AFTER `purchase_order`;

CREATE TABLE `subscribe_subscriber` (
  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `email` VARCHAR(50) NOT NULL,
  `sfid` INT(11) NOT NULL,
  `subscribe` TINYINT(4) NOT NULL DEFAULT '0',
  `unsubscribe` TINYINT(4) NOT NULL DEFAULT '0',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `nonce` VARCHAR(50) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE INDEX `email_sfid` (`email`, `sfid`),
  INDEX `nonce` (`nonce`)
)
  ENGINE=InnoDB
;

UPDATE xcart_payment_methods
SET frontend_processor_id = 3
WHERE paymentid IN (2,4);

UPDATE xcart_payment_methods
SET frontend_processor_id = 1
WHERE paymentid IN (17,100);

UPDATE xcart_payment_methods
SET frontend_processor_id = 4
WHERE paymentid IN (102,103,104,21);